import {
  booleanAttribute,
  computed,
  Directive,
  ElementRef,
  inject,
  input,
  model,
} from '@angular/core';
import { cn } from '@/lib/utils';

export {
  arcPath,
  areaPath,
  extent,
  linePath,
  niceTicks,
  pieArcs,
  scaleBand,
  scaleLinear,
  scaleTime,
  stack,
  type BandPadding,
  type BandScale,
  type ChartArc,
  type ChartCurve,
  type ChartPoint,
  type LinearScale,
  type PieOptions,
  type TimeScale,
} from '@/lib/chart';

/** A series' label and color, by its key. */
export type ChartConfig = Record<
  string,
  {
    /** The series' name, for tooltips and legends. */
    readonly label?: string;
    /** A CSS color, such as `var(--chart-1)`. */
    readonly color?: string;
    /** Colors for the light and dark themes, used with `light-dark()`. */
    readonly theme?: { readonly light: string; readonly dark: string };
  }
>;

/**
 * A chart's frame: it sets `--color-<key>` for each series in `config`,
 * so the SVG, tooltip and legend use `var(--color-desktop)`, and keeps
 * a video aspect ratio. Put it on a `figure` with a `figcaption`.
 *
 * @example
 * ```html
 * <figure ndChartContainer [config]="config">
 *   <figcaption>Visitors</figcaption>
 *   <svg ndChartPlot viewBox="0 0 500 250">…</svg>
 * </figure>
 * ```
 */
@Directive({
  selector: '[ndChartContainer]',
  host: {
    'data-slot': 'chart',
    '[style]': 'colors()',
    '[class]': 'classes()',
  },
})
export class ChartContainer {
  /** Each series' label and color, by key. */
  readonly config = input<ChartConfig>({});

  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly colors = computed(() =>
    Object.fromEntries(
      Object.entries(this.config()).flatMap(([key, item]) => {
        const color = item.theme
          ? `light-dark(${item.theme.light}, ${item.theme.dark})`
          : item.color;
        return color ? [[`--color-${key}`, color]] : [];
      }),
    ),
  );

  protected readonly classes = computed(() =>
    cn(
      'relative flex aspect-video justify-center text-xs [&_svg]:overflow-visible',
      this.class(),
    ),
  );
}

/**
 * The plot, on the chart's `svg`: one tab stop where the arrow keys,
 * `Home` and `End` move between data points and the pointer picks the
 * nearest one, setting `active`. Bind a tooltip and a polite live region
 * to `active`, so the keyboard and screen readers reach each value. Give
 * it `xs`, each point's horizontal position in `viewBox` units, and name
 * it with `aria-label` or `aria-labelledby`.
 *
 * @example
 * ```html
 * <svg ndChartPlot viewBox="0 0 500 250" [xs]="xs()" [(active)]="active" aria-label="Visitors by month">…</svg>
 * ```
 */
@Directive({
  selector: 'svg[ndChartPlot]',
  host: {
    'data-slot': 'chart-plot',
    role: 'group',
    tabindex: '0',
    '[attr.data-active]': 'active()',
    '[class]': 'classes()',
    '(keydown)': 'keydown($event)',
    '(pointermove)': 'pointer($event)',
    '(pointerleave)': 'leave()',
    '(focus)': 'focus()',
    '(blur)': 'active.set(null)',
  },
})
export class ChartPlot {
  /** Each data point's horizontal position, in `viewBox` units. */
  readonly xs = input<readonly number[]>([]);

  /** The index of the active data point, or `null`. Two-way bindable. */
  readonly active = model<number | null>(null);

  /**
   * Whether the pointer picks the point nearest it horizontally; turn it
   * off for pies, whose slices set `active` on hover themselves.
   */
  readonly trackPointer = input(true, { transform: booleanAttribute });

  /** Extra classes, merged last so they win. */
  readonly class = input('');

  private readonly element =
    inject<ElementRef<SVGSVGElement>>(ElementRef).nativeElement;

  protected readonly classes = computed(() =>
    cn(
      'h-full w-full rounded-md outline-hidden focus-visible:ring-[3px] focus-visible:ring-ring/50',
      this.class(),
    ),
  );

  /**
   * Moves between data points with the arrow keys, `Home` and `End`.
   *
   * @param event - The keydown event.
   */
  protected keydown(event: KeyboardEvent): void {
    const last = this.xs().length - 1;
    const current = this.active() ?? 0;
    let next: number;
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        next = Math.min(last, current + 1);
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        next = Math.max(0, current - 1);
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = last;
        break;
      case 'Escape':
        this.active.set(null);
        return;
      default:
        return;
    }
    event.preventDefault();
    this.active.set(next);
  }

  /**
   * Picks the data point nearest the pointer.
   *
   * @param event - The pointermove event.
   */
  protected pointer(event: PointerEvent): void {
    const matrix = this.element.getScreenCTM?.();
    const xs = this.xs();
    if (!this.trackPointer() || !matrix || xs.length === 0) {
      return;
    }
    // From screen pixels to viewBox units, whatever the SVG's size.
    const x = (event.clientX - matrix.e) / matrix.a;
    let nearest = 0;
    xs.forEach((value, index) => {
      if (Math.abs(value - x) < Math.abs((xs[nearest] as number) - x)) {
        nearest = index;
      }
    });
    this.active.set(nearest);
  }

  /** Clears the active point when the pointer leaves, unless focused. */
  protected leave(): void {
    if (this.element.ownerDocument.activeElement !== this.element) {
      this.active.set(null);
    }
  }

  /** Activates the first point when focus arrives from the keyboard. */
  protected focus(): void {
    if (this.active() === null && this.xs().length > 0) {
      this.active.set(0);
    }
  }
}

/**
 * The grid lines behind the data, on a `g`.
 *
 * @example
 * ```html
 * <g ndChartGrid>…<line /></g>
 * ```
 */
@Directive({
  selector: '[ndChartGrid]',
  host: { 'data-slot': 'chart-grid', '[class]': 'classes()' },
})
export class ChartGrid {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn('[&_line]:stroke-border/50', this.class()),
  );
}

/**
 * An axis' labels, on a `g`.
 *
 * @example
 * ```html
 * <g ndChartAxis>…<text>Jan</text></g>
 * ```
 */
@Directive({
  selector: '[ndChartAxis]',
  host: { 'data-slot': 'chart-axis', '[class]': 'classes()' },
})
export class ChartAxis {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn('[&_text]:fill-muted-foreground', this.class()),
  );
}

/**
 * The marker of the active data point: a line, or a band behind bars.
 *
 * @example
 * ```html
 * <rect ndChartCursor kind="band" … />
 * ```
 */
@Directive({
  selector: '[ndChartCursor]',
  host: {
    'data-slot': 'chart-cursor',
    'aria-hidden': 'true',
    '[attr.data-kind]': 'kind()',
    '[class]': 'classes()',
  },
})
export class ChartCursor {
  /** `line` for line and area charts, `band` for bars. */
  readonly kind = input<'line' | 'band'>('line');

  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn(
      'pointer-events-none data-[kind=band]:fill-muted data-[kind=line]:stroke-border',
      this.class(),
    ),
  );
}

/**
 * The tooltip of the active data point, drawn over the chart. It's for
 * sighted users; a polite live region tells screen readers the same.
 *
 * @example
 * ```html
 * <div ndChartTooltip [style.left.%]="left()">…</div>
 * ```
 */
@Directive({
  selector: '[ndChartTooltip]',
  host: {
    'data-slot': 'chart-tooltip',
    'aria-hidden': 'true',
    '[class]': 'classes()',
  },
})
export class ChartTooltip {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn(
      'grid min-w-[8rem] items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl',
      'pointer-events-none absolute top-0 z-10 -translate-x-1/2',
      this.class(),
    ),
  );
}

/**
 * The tooltip's heading, such as the month.
 *
 * @example
 * ```html
 * <div ndChartTooltipLabel>January</div>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipLabel]',
  host: { 'data-slot': 'chart-tooltip-label', '[class]': 'classes()' },
})
export class ChartTooltipLabel {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() => cn('font-medium', this.class()));
}

/**
 * The list of a tooltip's series.
 *
 * @example
 * ```html
 * <div ndChartTooltipList>…</div>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipList]',
  host: { 'data-slot': 'chart-tooltip-list', '[class]': 'classes()' },
})
export class ChartTooltipList {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() => cn('grid gap-1.5', this.class()));
}

/**
 * One series in a tooltip: its indicator, name and value.
 *
 * @example
 * ```html
 * <div ndChartTooltipItem>…</div>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipItem]',
  host: { 'data-slot': 'chart-tooltip-item', '[class]': 'classes()' },
})
export class ChartTooltipItem {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn(
      'flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground',
      'items-center',
      this.class(),
    ),
  );
}

/**
 * A series' color swatch in a tooltip: a `dot`, a `line` or a `dashed`
 * line.
 *
 * @example
 * ```html
 * <span ndChartTooltipIndicator color="var(--color-desktop)"></span>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipIndicator]',
  host: {
    'data-slot': 'chart-tooltip-indicator',
    '[style.--color-bg]': 'color()',
    '[style.--color-border]': 'color()',
    '[class]': 'classes()',
  },
})
export class ChartTooltipIndicator {
  /** Its shape. */
  readonly indicator = input<'dot' | 'line' | 'dashed'>('dot');

  /** The series' color. */
  readonly color = input('currentColor');

  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn(
      'shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)',
      this.indicator() === 'dot' && 'h-2.5 w-2.5',
      this.indicator() === 'line' && 'w-1',
      this.indicator() === 'dashed' &&
        'w-0 border-[1.5px] border-dashed bg-transparent',
      this.class(),
    ),
  );
}

/**
 * The name and value of a series in a tooltip, spread across its width.
 *
 * @example
 * ```html
 * <div ndChartTooltipBody>
 *   <span ndChartTooltipName>Desktop</span>
 *   <span ndChartTooltipValue>186</span>
 * </div>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipBody]',
  host: { 'data-slot': 'chart-tooltip-body', '[class]': 'classes()' },
})
export class ChartTooltipBody {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn(
      'flex flex-1 justify-between leading-none',
      'items-center',
      this.class(),
    ),
  );
}

/**
 * A series' name in a tooltip.
 *
 * @example
 * ```html
 * <span ndChartTooltipName>Desktop</span>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipName]',
  host: { 'data-slot': 'chart-tooltip-name', '[class]': 'classes()' },
})
export class ChartTooltipName {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn('text-muted-foreground', this.class()),
  );
}

/**
 * A series' value in a tooltip, in tabular figures.
 *
 * @example
 * ```html
 * <span ndChartTooltipValue>186</span>
 * ```
 */
@Directive({
  selector: '[ndChartTooltipValue]',
  host: { 'data-slot': 'chart-tooltip-value', '[class]': 'classes()' },
})
export class ChartTooltipValue {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn('font-mono font-medium text-foreground tabular-nums', this.class()),
  );
}

/**
 * The legend: the series' swatches and names, under the chart.
 *
 * @example
 * ```html
 * <ul ndChartLegend>…</ul>
 * ```
 */
@Directive({
  selector: '[ndChartLegend]',
  host: { 'data-slot': 'chart-legend', '[class]': 'classes()' },
})
export class ChartLegend {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn('flex items-center justify-center gap-4', 'pt-3', this.class()),
  );
}

/**
 * One series in the legend.
 *
 * @example
 * ```html
 * <li ndChartLegendItem>…</li>
 * ```
 */
@Directive({
  selector: '[ndChartLegendItem]',
  host: { 'data-slot': 'chart-legend-item', '[class]': 'classes()' },
})
export class ChartLegendItem {
  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn(
      'flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground',
      this.class(),
    ),
  );
}

/**
 * A series' color swatch in the legend.
 *
 * @example
 * ```html
 * <span ndChartLegendIndicator color="var(--color-desktop)"></span>
 * ```
 */
@Directive({
  selector: '[ndChartLegendIndicator]',
  host: {
    'data-slot': 'chart-legend-indicator',
    '[style.background-color]': 'color()',
    '[class]': 'classes()',
  },
})
export class ChartLegendIndicator {
  /** The series' color. */
  readonly color = input('currentColor');

  /** Extra classes, merged last so they win. */
  readonly class = input('');

  protected readonly classes = computed(() =>
    cn('h-2 w-2 shrink-0 rounded-[2px]', this.class()),
  );
}

/** A point in SVG user units. */
export interface ChartPoint {
  /** Horizontal position. */
  readonly x: number;
  /** Vertical position. */
  readonly y: number;
}

/** How a line or area joins its points. */
export type ChartCurve = 'linear' | 'monotone' | 'step';

/** A scale from numbers to positions, as from data to pixels. */
export interface LinearScale {
  /**
   * The position of a value.
   *
   * @param value - A value in the domain.
   * @returns Its position in the range.
   */
  (value: number): number;
  /** The domain, after `nice`. */
  readonly domain: readonly [number, number];
  /**
   * Round values across the domain, for axis labels and grid lines.
   *
   * @param count - About how many; defaults to 5.
   * @returns The values.
   */
  ticks(count?: number): number[];
}

/** A scale from categories to bands, as for bars. */
export interface BandScale {
  /**
   * Where a category's band starts.
   *
   * @param key - A category in the domain.
   * @returns The band's start, or `NaN` for an unknown category.
   */
  (key: string): number;
  /** The width of each band. */
  readonly bandwidth: number;
  /** The distance from one band's start to the next one's. */
  readonly step: number;
}

/** A scale from dates to positions. */
export interface TimeScale {
  /**
   * The position of a date.
   *
   * @param value - A date in the domain.
   * @returns Its position in the range.
   */
  (value: Date): number;
  /**
   * Dates at round intervals across the domain: days, weeks, months or
   * years, whichever gives about `count`.
   *
   * @param count - About how many; defaults to 5.
   * @returns The dates.
   */
  ticks(count?: number): Date[];
}

/** One slice of a pie, donut or radial chart. */
export interface ChartArc {
  /** Where it starts, in radians clockwise from 12 o'clock. */
  readonly startAngle: number;
  /** Where it ends, in radians. */
  readonly endAngle: number;
  /** Its value. */
  readonly value: number;
  /** Its index in the values. */
  readonly index: number;
}

/** Space around a {@link BandScale}'s bands, in fractions of a step. */
export interface BandPadding {
  /** Space between bands; defaults to 0.2. */
  readonly inner?: number;
  /** Space before the first band and after the last; defaults to 0.2. */
  readonly outer?: number;
}

/** The angles a pie spans, for {@link pieArcs}. */
export interface PieOptions {
  /** Where the first slice starts, in radians clockwise from 12 o'clock. */
  readonly startAngle?: number;
  /** Where the last slice ends; defaults to a full turn after 0. */
  readonly endAngle?: number;
  /** The gap between slices, in radians; defaults to 0. */
  readonly padAngle?: number;
}

/**
 * The smallest and largest of some numbers.
 *
 * @param values - The numbers.
 * @returns `[min, max]`, or `[0, 0]` for none.
 */
export function extent(values: readonly number[]): [number, number] {
  if (values.length === 0) {
    return [0, 0];
  }
  return [Math.min(...values), Math.max(...values)];
}

/**
 * A round step for about `count` ticks between two values: 1, 2 or 5
 * times a power of ten.
 *
 * @param min - The lower value.
 * @param max - The upper value.
 * @param count - About how many ticks.
 * @returns The step.
 */
function tickStep(min: number, max: number, count: number): number {
  const raw = Math.abs(max - min) / Math.max(1, count);
  const power = 10 ** Math.floor(Math.log10(raw || 1));
  const error = raw / power;
  const factor = error >= 7.5 ? 10 : error >= 3.5 ? 5 : error >= 1.5 ? 2 : 1;
  return factor * power;
}

/**
 * Round values from `min` to `max`, about `count` of them.
 *
 * @param min - The lower value.
 * @param max - The upper value.
 * @param count - About how many; defaults to 5.
 * @returns The values, ascending.
 */
export function niceTicks(min: number, max: number, count = 5): number[] {
  if (min === max) {
    return [min];
  }
  const step = tickStep(min, max, count);
  const start = Math.ceil(min / step) * step;
  const ticks: number[] = [];
  for (let value = start; value <= max + step / 1e6; value += step) {
    // Rounds away floating point noise, such as 0.30000000000000004.
    ticks.push(Number(value.toPrecision(12)));
  }
  return ticks;
}

/**
 * A linear scale. With `nice`, the domain extends to round values, so the
 * axis starts and ends on a tick.
 *
 * @param domain - The values, `[min, max]`.
 * @param range - The positions, `[start, end]`; reversed works, as for a
 *   y axis that grows upward.
 * @param nice - Whether to round the domain out; defaults to `true`.
 * @returns The scale.
 *
 * @example
 * ```ts
 * const y = scaleLinear([0, 305], [200, 0]);
 * y(150); // 100
 * ```
 */
export function scaleLinear(
  domain: readonly [number, number],
  range: readonly [number, number],
  nice = true,
): LinearScale {
  let [d0, d1] = domain;
  if (nice && d0 !== d1) {
    const step = tickStep(d0, d1, 5);
    d0 = Math.floor(d0 / step) * step;
    d1 = Math.ceil(d1 / step) * step;
  }
  const [r0, r1] = range;
  const span = d1 - d0 || 1;
  const scale = ((value: number) =>
    r0 + ((value - d0) / span) * (r1 - r0)) as LinearScale;
  Object.assign(scale, {
    domain: [d0, d1] as const,
    ticks: (count = 5) => niceTicks(d0, d1, count),
  });
  return scale;
}

/**
 * A band scale: the range split into one band per category, with padding
 * between bands and at the ends, in fractions of a step.
 *
 * @param domain - The categories, in order.
 * @param range - The positions, `[start, end]`.
 * @param padding - Space between bands and at the ends.
 * @returns The scale.
 *
 * @example
 * ```ts
 * const x = scaleBand(['Jan', 'Feb'], [0, 400]);
 * x('Feb'); // where February's bar starts
 * x.bandwidth; // the bar's width
 * ```
 */
export function scaleBand(
  domain: readonly string[],
  range: readonly [number, number],
  padding: BandPadding = {},
): BandScale {
  const inner = padding.inner ?? 0.2;
  const outer = padding.outer ?? 0.2;
  const [r0, r1] = range;
  const step = (r1 - r0) / Math.max(1, domain.length - inner + outer * 2);
  const index = new Map(domain.map((key, i) => [key, i]));
  const scale = ((key: string) => {
    const i = index.get(key);
    return i === undefined ? Number.NaN : r0 + step * (outer + i);
  }) as BandScale;
  Object.assign(scale, { bandwidth: step * (1 - inner), step });
  return scale;
}

/** Time intervals for ticks, shortest first. */
const INTERVALS = [
  { days: 1, months: 0 },
  { days: 7, months: 0 },
  { days: 0, months: 1 },
  { days: 0, months: 3 },
  { days: 0, months: 12 },
] as const;

/**
 * A time scale: linear on timestamps, with ticks on round days, weeks,
 * months or years.
 *
 * @param domain - The dates, `[first, last]`.
 * @param range - The positions, `[start, end]`.
 * @returns The scale.
 *
 * @example
 * ```ts
 * const x = scaleTime([new Date(2026, 0, 1), new Date(2026, 5, 30)], [0, 600]);
 * x.ticks(6); // the 1st of each month
 * ```
 */
export function scaleTime(
  domain: readonly [Date, Date],
  range: readonly [number, number],
): TimeScale {
  const [d0, d1] = domain.map((date) => date.getTime()) as [number, number];
  const linear = scaleLinear([d0, d1], range, false);
  const scale = ((value: Date) => linear(value.getTime())) as TimeScale;
  Object.assign(scale, {
    ticks(count = 5) {
      const days = (d1 - d0) / 86_400_000;
      const interval =
        INTERVALS.find(
          (option) => days / (option.days || option.months * 30.4) <= count,
        ) ?? INTERVALS[4];
      const first = new Date(d0);
      let date =
        interval.months > 0
          ? new Date(first.getFullYear(), first.getMonth(), 1)
          : new Date(first.getFullYear(), first.getMonth(), first.getDate());
      const ticks: Date[] = [];
      while (date.getTime() <= d1) {
        if (date.getTime() >= d0) {
          ticks.push(date);
        }
        date =
          interval.months > 0
            ? new Date(date.getFullYear(), date.getMonth() + interval.months, 1)
            : new Date(
                date.getFullYear(),
                date.getMonth(),
                date.getDate() + interval.days,
              );
      }
      return ticks;
    },
  });
  return scale;
}

/**
 * Formats a number for an SVG path, short and without noise.
 *
 * @param value - The number.
 * @returns Its text.
 */
function n(value: number): string {
  return String(Math.round(value * 100) / 100);
}

/**
 * The slopes of a monotone cubic through points, which never overshoot
 * them (Fritsch–Carlson).
 *
 * @param points - The points, by ascending x.
 * @returns One tangent per point.
 */
function monotoneTangents(points: readonly ChartPoint[]): number[] {
  const count = points.length;
  const slopes: number[] = [];
  for (let i = 0; i < count - 1; i++) {
    const a = points[i] as ChartPoint;
    const b = points[i + 1] as ChartPoint;
    slopes.push((b.y - a.y) / (b.x - a.x || 1));
  }
  const tangents = points.map((_, i) => {
    if (i === 0) return slopes[0] ?? 0;
    if (i === count - 1) return slopes[count - 2] ?? 0;
    const before = slopes[i - 1] as number;
    const after = slopes[i] as number;
    return before * after <= 0 ? 0 : (before + after) / 2;
  });
  for (let i = 0; i < count - 1; i++) {
    const slope = slopes[i] as number;
    if (slope === 0) {
      tangents[i] = 0;
      tangents[i + 1] = 0;
      continue;
    }
    const alpha = (tangents[i] as number) / slope;
    const beta = (tangents[i + 1] as number) / slope;
    const length = alpha * alpha + beta * beta;
    if (length > 9) {
      const tau = 3 / Math.sqrt(length);
      tangents[i] = tau * alpha * slope;
      tangents[i + 1] = tau * beta * slope;
    }
  }
  return tangents;
}

/**
 * The path segments through points, after a first `M`.
 *
 * @param points - The points, by ascending x.
 * @param curve - How to join them.
 * @returns The segments, as SVG path commands.
 */
function segments(points: readonly ChartPoint[], curve: ChartCurve): string {
  let path = '';
  if (curve === 'monotone' && points.length > 2) {
    const tangents = monotoneTangents(points);
    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i] as ChartPoint;
      const b = points[i + 1] as ChartPoint;
      const dx = (b.x - a.x) / 3;
      path += `C${n(a.x + dx)},${n(a.y + dx * (tangents[i] as number))},${n(b.x - dx)},${n(b.y - dx * (tangents[i + 1] as number))},${n(b.x)},${n(b.y)}`;
    }
    return path;
  }
  for (let i = 1; i < points.length; i++) {
    const point = points[i] as ChartPoint;
    if (curve === 'step') {
      const previous = points[i - 1] as ChartPoint;
      const middle = (previous.x + point.x) / 2;
      path += `H${n(middle)}V${n(point.y)}H${n(point.x)}`;
    } else {
      path += `L${n(point.x)},${n(point.y)}`;
    }
  }
  return path;
}

/**
 * An SVG path through points, for a line chart.
 *
 * @param points - The points, by ascending x.
 * @param curve - How to join them; defaults to `linear`.
 * @returns The path's `d`, or an empty string for no points.
 *
 * @example
 * ```html
 * <path [attr.d]="linePath(points(), 'monotone')" />
 * ```
 */
export function linePath(
  points: readonly ChartPoint[],
  curve: ChartCurve = 'linear',
): string {
  const [first] = points;
  return first ? `M${n(first.x)},${n(first.y)}${segments(points, curve)}` : '';
}

/**
 * An SVG path filling between a line through points and a baseline, for
 * an area chart. With `lower` points, as for a stacked series, it fills
 * between the two lines.
 *
 * @param points - The top points, by ascending x.
 * @param baseline - The bottom's y, or the bottom points.
 * @param curve - How to join them; defaults to `linear`.
 * @returns The path's `d`, or an empty string for no points.
 */
export function areaPath(
  points: readonly ChartPoint[],
  baseline: number | readonly ChartPoint[],
  curve: ChartCurve = 'linear',
): string {
  const [first] = points;
  const last = points[points.length - 1];
  if (!first || !last) {
    return '';
  }
  const top = `M${n(first.x)},${n(first.y)}${segments(points, curve)}`;
  if (typeof baseline === 'number') {
    return `${top}L${n(last.x)},${n(baseline)}L${n(first.x)},${n(baseline)}Z`;
  }
  const lower = [...baseline].reverse();
  const start = lower[0] as ChartPoint;
  return `${top}L${n(start.x)},${n(start.y)}${segments(lower, curve)}Z`;
}

/**
 * An SVG path for a slice of a ring, centered on 0,0: a pie slice when
 * `innerRadius` is 0, a donut segment or a radial bar otherwise.
 *
 * @param arc - The slice's angles, in radians clockwise from 12 o'clock.
 * @param innerRadius - The hole's radius; 0 for a pie.
 * @param outerRadius - The slice's radius.
 * @returns The path's `d`.
 *
 * @example
 * ```html
 * <path [attr.d]="arcPath(slice, 60, 100)" transform="translate(120 120)" />
 * ```
 */
export function arcPath(
  arc: Pick<ChartArc, 'startAngle' | 'endAngle'>,
  innerRadius: number,
  outerRadius: number,
): string {
  // A full circle as one arc has equal ends, which SVG draws as nothing.
  const end = Math.min(arc.endAngle, arc.startAngle + Math.PI * 2 - 1e-6);
  const point = (radius: number, angle: number) =>
    `${n(radius * Math.sin(angle))},${n(-radius * Math.cos(angle))}`;
  const large = end - arc.startAngle > Math.PI ? 1 : 0;
  const outer = `M${point(outerRadius, arc.startAngle)}A${n(outerRadius)},${n(outerRadius)},0,${large},1,${point(outerRadius, end)}`;
  if (innerRadius <= 0) {
    return `${outer}L0,0Z`;
  }
  return `${outer}L${point(innerRadius, end)}A${n(innerRadius)},${n(innerRadius)},0,${large},0,${point(innerRadius, arc.startAngle)}Z`;
}

/**
 * The angles of a pie's slices, in order, each proportional to its value.
 *
 * @param values - The values; negatives count as 0.
 * @param options - The angles to span and the gap between slices.
 * @returns One arc per value.
 */
export function pieArcs(
  values: readonly number[],
  options: PieOptions = {},
): ChartArc[] {
  const start = options.startAngle ?? 0;
  const span = (options.endAngle ?? Math.PI * 2) - start;
  const pad = options.padAngle ?? 0;
  const total = values.reduce((sum, value) => sum + Math.max(0, value), 0);
  let angle = start;
  return values.map((value, index) => {
    const share = total > 0 ? (Math.max(0, value) / total) * span : 0;
    const arc = {
      startAngle: angle + pad / 2,
      endAngle: Math.max(angle + pad / 2, angle + share - pad / 2),
      value,
      index,
    };
    angle += share;
    return arc;
  });
}

/**
 * Stacks series on top of each other, as for stacked bars or areas.
 *
 * @param series - Each series' values, in the same order.
 * @returns For each series, each value's `[bottom, top]`.
 *
 * @example
 * ```ts
 * stack([[1, 2], [3, 4]]); // [[[0, 1], [0, 2]], [[1, 4], [2, 6]]]
 * ```
 */
export function stack(
  series: readonly (readonly number[])[],
): [number, number][][] {
  const totals: number[] = [];
  return series.map((values) =>
    values.map((value, index) => {
      const bottom = totals[index] ?? 0;
      totals[index] = bottom + value;
      return [bottom, bottom + value];
    }),
  );
}
